#!/usr/bin/env bash
set -e
cd /workspaces/ExpenseFlow-

mkdir -p "$(dirname 'lib/features/dashboard/presentation/screens/dashboard_screen.dart')"
echo '' | base64 -d > 'lib/features/dashboard/presentation/screens/dashboard_screen.dart'
echo 'Updated lib/features/dashboard/presentation/screens/dashboard_screen.dart'

mkdir -p "$(dirname 'lib/features/transactions/presentation/screens/transactions_screen.dart')"
echo '' | base64 -d > 'lib/features/transactions/presentation/screens/transactions_screen.dart'
echo 'Updated lib/features/transactions/presentation/screens/transactions_screen.dart'

mkdir -p "$(dirname 'lib/features/analytics/presentation/screens/analysis_screen.dart')"
echo '' | base64 -d > 'lib/features/analytics/presentation/screens/analysis_screen.dart'
echo 'Updated lib/features/analytics/presentation/screens/analysis_screen.dart'

echo 'ExpenseFlow update applied.'
flutter analyze